import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Card, Rate, Row } from 'antd'

import { StatusWiseRatingStyle } from './component.style'
import { Header } from '../../../../../components/StyledComponents'

class StatusWiseRating extends Component {
  showRating = (heading, ratingCount) => {
    return (
      <div>
        <Header content={heading} />
        <div>Average</div>
        <Row justify='space-between' align='middle'>
          <Rate disabled value={ratingCount} />
          <div className='count'>{ratingCount}</div>
        </Row>
      </div>
    )
  }

  render() {
    const { feedbackDashboardData = {} } = this.props
    const {
      avg_settled_claim_rating: avgSettledClaimRating = 0,
      avg_rejected_claim_rating: avgRejectedClaimRating = 0
    } = feedbackDashboardData
    return (
      <StatusWiseRatingStyle>
        <Row justify='space-between'>
          <Card>
            {this.showRating('SETTLED CLAIMS', avgSettledClaimRating)}
          </Card>
          <Card>
            {this.showRating('REJECTED CLAIMS', avgRejectedClaimRating)}
          </Card>
        </Row>
      </StatusWiseRatingStyle>
    )
  }
}

export default connect(state => ({
  feedbackDashboardData: state.Claim.feedbackDashboardData
}), {
})(StatusWiseRating)
