import React, { Component } from 'react'
import { connect } from 'react-redux'
import { DatePicker, Form, Select, Row } from 'antd'
import moment from 'moment'
import { get } from 'lodash'

import { ComponentStyle } from './component.style'
import policyActions from '../../../../redux/policy/action'
import { RATING_LIST } from './constants'

const { getProductsList } = policyActions

const DATE_FORMAT = 'YYYY-MM-DD'

const FormItem = Form.Item
const { Option } = Select

class Filters extends Component {
  constructor(props) {
    super(props)
    this.formRef = React.createRef()
  }

  componentDidMount() {
    const { startDate, endDate, partners, productKey, rating } = this.props
    if (startDate || endDate || partners || productKey || rating) {
      this.formRef.current.setFieldsValue({
        startDate: moment(startDate),
        endDate: moment(endDate),
        partners: partners,
        productKey: productKey,
        rating: rating
      })
    }
  }

  handleFieldsChange = (_, values) => { 
    values = {
      ...values,
      startDate: get(values, 'startDate').format('YYYY-MM-DD'),
      endDate: get(values, 'endDate').format('YYYY-MM-DD')
    }
    this.props.fetch(values)
  }

  handlePartnerChange = partner => {
    this.props.getProductsList({
      query: {
        partnerCodes: partner
      }
    })
  }

  disabledStartDate = current => {
    const endDate = this.formRef.current.getFieldValue(['endDate'])

    return current && current.valueOf() > endDate
  }

  disabledEndDate = current => {
    const startDate = this.formRef.current.getFieldValue(['startDate'])

    return current && (current.valueOf() > Date.now() || current.valueOf() < startDate)
  }

  render() {
    const { partnersList = [], productsList = [], productListLoading, partnerListLoading } = this.props

    return (
      <ComponentStyle>
        <Form onValuesChange={this.handleFieldsChange} ref={this.formRef}>
          <Row>
            <div>
              <div className='head'>From</div>
              <FormItem name='startDate' className='filter' initialValue={moment().clone().subtract(7, 'days')}>
                <DatePicker
                  allowClear={false}
                  format={DATE_FORMAT}
                  disabledDate={this.disabledStartDate}
                />
              </FormItem>
            </div>
            <div>
              <div className='head'>To</div>
              <FormItem name='endDate' colon={false} className='filter' initialValue={moment()}>
                <DatePicker
                  allowClear={false}
                  format={DATE_FORMAT}
                  disabledDate={this.disabledEndDate}
                />
              </FormItem>
            </div>
            <div>
              <div className='head'>Partner</div>
              <FormItem name='partners' className='filter'>
                <Select
                  showSearch
                  placeholder='Select Partner'
                  optionFilterProp="children"
                  allowClear
                  loading={!!partnerListLoading}
                  disabled={!!partnerListLoading}
                  dropdownMatchSelectWidth={false}
                  onChange={this.handlePartnerChange}
                  filterOption={(input, option) =>
                    option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
                  }
                >
                  {
                    partnersList.map(({ name, code }) => <Option key={code} value={code}>{name}</Option>)
                  }
                </Select>
              </FormItem>
            </div>
            <div>
              <div className='head'>Product</div>
              <FormItem name='productKey' className='filter'>
                <Select
                  showSearch
                  placeholder='Select Products'
                  optionFilterProp="children"
                  allowClear
                  loading={!!productListLoading}
                  disabled={!!productListLoading}
                  dropdownMatchSelectWidth={false}
                  filterOption={(input, option) =>
                    option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
                  }
                >
                  {
                    productsList.map(({ display_name: displayName, name }) => <Option key={name} value={name}>{displayName}</Option>)
                  }
                </Select>
              </FormItem>
            </div>
            <div>
              <div className='head'>Rating</div>
              <FormItem name='rating' className='filter'>
                <Select
                  showSearch
                  placeholder='Select Rating'
                  optionFilterProp="children"
                  allowClear
                  dropdownMatchSelectWidth={false}
                  filterOption={(input, option) =>
                    option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
                  }
                >
                  {
                    RATING_LIST.map(({ value, name }) => <Option key={value} value={value}>{name}</Option>)
                  }
                </Select>
              </FormItem>
            </div>
          </Row>
        </Form>
      </ComponentStyle>
    )
  }
}

export default connect(state => ({
  partnerListLoading: state.Loading.GET_PARTNERS_LIST,
  partnersList: state.Policy.partnersList,

  productListLoading: state.Loading.GET_PRODUCTS_LIST,
  productsList: state.Policy.productsList
}), {
  getProductsList
})(Filters)
