import React from 'react'
import { filter, map } from "lodash"

import PermissionChecker from '../../../../../components/PermissionChecker'
import ConfigChecker from '../../../../../components/ConfigChecker'

export const RATING_LIST = [
  { value: 1, name: 'Rating 1' },
  { value: 2, name: 'Rating 2' },
  { value: 3, name: 'Rating 3' },
  { value: 4, name: 'Rating 4' },
  { value: 5, name: 'Rating 5' },
]

const CheckPermission = ({children}) => {
  return (
    <PermissionChecker requiredPermission={"view_claim_details"}>
      <ConfigChecker
        requiredConfig={"DISPLAY_CLAIM_DETAILS"}
        requiredValue="1"
      >
        {children}
      </ConfigChecker>
    </PermissionChecker>)
}


export const FeedbackTableColumns = (props) => [{
  title: <CheckPermission>Action</CheckPermission>,
  key: 'action',
  dataIndex: 'claim_id',
  render: id => (
    <CheckPermission>
      <div className='detail-button' onClick={() => props.handleClickDetail(id)}>Detail</div>
    </CheckPermission>
  )
}, {
  title: 'Claim Number',
  key: 'claim_number',
  dataIndex: 'claim_number'
}, {
  title: 'Rating',
  key: 'rating',
  dataIndex: 'rating'
}, {
  title: 'Feedback',
  key: 'feedback_data',
  dataIndex: 'feedback_data',
  render: feedback => {
    const isSelectedData = filter(feedback['options'], 'is_selected')
    return map(isSelectedData, 'label').join(', ')
  }
}, {
  title: 'Comment',
  key: 'comment',
  dataIndex: 'comment'
},]