import React, { Component } from 'react'
import { CountCardStyle } from './styledComponent.style'
import { Row, Col } from 'antd'

class CountCard extends Component {
  render() {
    const { icon, title, value, color } = this.props

    return (
      <CountCardStyle color={color}>
        <Row>
          <Col span={6} className='icon-wrapper'>
            {icon}
          </Col>
          <Col className='data-wrapper'>
            <div className='value'>{value}</div>
            <div className='title'>{title}</div>
          </Col>
        </Row>
      </CountCardStyle>
    )
  }
}

export default CountCard
