import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Row } from 'antd'

import { Header } from '../../../../../components/StyledComponents'
import { OverallRatingStyle, CountStyle } from './component.style'
import { GENERIC_IMAGES } from '../../../../../constants/images'
import claimActions from '../../../../redux/claims/actions'

const { getFeedbackListData } = claimActions

class OverallRating extends Component {
  handleCountClick = (eventCode) => {
    const { filterValues } = this.props
    switch (eventCode) {
      case 'settled':
      case 'rejected':
        return this.props.history.push('/customer-feedback/list/', { eventCode, ...filterValues })
      case 'totalFeedback':
        return this.props.history.push('/customer-feedback/list/', { ...filterValues })
      default:
        return
    }
  }

  getImage = (iconCode) => {
    const { TOTAL_CLAIMS_ICON, SETTLED_CLAIMS_ICON, REJECTED_CLAIMS_ICON, TOTAL_FEEDBACK_ICON } = GENERIC_IMAGES

    switch (iconCode) {
      case 'totalClaims':
        return TOTAL_CLAIMS_ICON
      case 'settled':
        return SETTLED_CLAIMS_ICON
      case 'rejected':
        return REJECTED_CLAIMS_ICON
      default:
        return TOTAL_FEEDBACK_ICON
    }
  }

  renderRatingCount = (heading, count, iconCode, color) => {
    return <CountStyle colorCode={color}>
      <Row align='middle'>
        <img src={this.getImage(iconCode, color)} className='img' width={36} alt="claim-status" />
        <span className='heading'>{heading}</span>
      </Row>
      <div className={`count ${iconCode !== 'totalClaims' && 'hover-text'}`} onClick={() => this.handleCountClick(iconCode)}>
        {count}
      </div>
    </CountStyle>
  }

  render() {
    const { feedbackDashboardData = {} } = this.props
    const {
      total_claims_count: totalClaimsCount = 0,
      total_claim_settled_feedback_count: avgSettledClaimCount = 0,
      total_claim_rejected_feedback_count: avgRejectedClaimCount = 0,
      total_claim_feedback_count: totalClaimFeedbackCount = 0
    } = feedbackDashboardData

    return (
      <OverallRatingStyle>
        <Header content="CUSTOMER FEEDBACK" />
        <Row justify='space-around'>
          {this.renderRatingCount('Total Claims', totalClaimsCount, 'totalClaims', '#FCBA3C')}
          {this.renderRatingCount('Total Feedback From Settled Claims', avgSettledClaimCount, 'settled', '#278A5D')}
          {this.renderRatingCount('Total Feedback From Rejected Claims', avgRejectedClaimCount, 'rejected', '#F3463B')}
          {this.renderRatingCount('Total Feedback', totalClaimFeedbackCount, 'totalFeedback', '#4487ED')}
        </Row>
      </OverallRatingStyle>
    )
  }
}

export default connect(state => ({
  feedbackDashboardData: state.Claim.feedbackDashboardData
}), {
  getFeedbackListData
})(OverallRating)
